def gen(rng):
    def ip(x):
        return '%d.%d.%d.%d' % ((x >> 24) & 255, (x >> 16) & 255, (x >> 8) & 255, x & 255)
    def mask(x, L):
        return (x >> (32 - L)) << (32 - L) if L else 0
    def build(n, q, lens, region_bits=None, nest=False, near=0.8):
        # region_bits: restrict addresses to a small region to force overlaps
        def rnd():
            x = rng.getrandbits(32)
            if region_bits:
                x = (x & ((1 << (32 - region_bits[0])) - 1)) | region_bits[1]
            return x
        rules = {}
        tries = 0
        if nest:
            base = rnd()
            for L in range(0, 33):
                if len(rules) < n:
                    rules[(mask(base, L), L)] = rng.randint(0, 10**9)
        while len(rules) < n and tries < n * 50:
            tries += 1
            L = rng.choice(lens)
            rules[(mask(rnd(), L), L)] = rng.randint(0, 10**9)
        rl = list(rules.items())
        rng.shuffle(rl)
        lines = ['%d %d' % (len(rl), q)]
        for (a, L), h in rl:
            lines.append('%s/%d %d' % (ip(a), L, h))
        for _ in range(q):
            if rl and rng.random() < near:
                (a, L), _h = rng.choice(rl)
                x = a | (rng.getrandbits(32 - L) if L < 32 else 0)
            else:
                x = rnd()
            lines.append(ip(x))
        return '\n'.join(lines)
    tests = [
        '1 1\n0.0.0.0/0 5\n255.255.255.255',
        '1 2\n1.2.3.4/32 0\n1.2.3.4\n1.2.3.5',
        '2 3\n128.0.0.0/1 4\n0.0.0.0/1 8\n200.1.1.1\n3.3.3.3\n127.255.255.255',
        '2 2\n255.255.255.255/32 1\n255.255.255.254/31 2\n255.255.255.254\n255.255.255.255',
    ]
    for _ in range(14):
        n = rng.randint(1, 8)
        q = rng.randint(1, 8)
        lens = rng.choice([[0, 1, 2, 3, 4, 5, 6, 7, 8], [8, 16, 24, 32], list(range(0, 33))])
        rb = rng.choice([None, (4, 0xA0000000), (24, 0xC0A80100)])
        tests.append(build(n, q, lens, rb, nest=rng.random() < 0.3))
    # large tests
    N = 30000
    tests.append(build(N, N, list(range(0, 33)), None, near=0.9))
    tests.append(build(N, N, [24, 28, 30, 32], (8, 0x0A000000), nest=True, near=0.95))
    tests.append(build(N, N, list(range(16, 33)), (16, 0xC0A80000), nest=True, near=0.9))
    tests.append(build(N, N, [8, 16, 24, 32], None, near=0.5))
    return tests

